from collections import defaultdict

# Group reviews by business_id
reviews_by_business = defaultdict(list)
for r in dataset:
    reviews_by_business[r['business_id']].append(r['text'])

print(f"Number of businesses: {len(reviews_by_business)}")

# Find reviews that mention "service" for each business
service_reviews_by_business = {}
for bid, reviews in reviews_by_business.items():
    service_reviews = [r for r in reviews if 'service' in r.lower()]
    if service_reviews:
        service_reviews_by_business[bid] = service_reviews

print(f"Businesses with service mentions: {len(service_reviews_by_business)}")

# Let's see the count of service reviews per business
for bid, reviews in sorted(service_reviews_by_business.items(), key=lambda x: len(x[1]), reverse=True)[:10]:
    print(f"  {bid}: {len(reviews)} service reviews (out of {len(reviews_by_business[bid])} total)")
